mapper.select:
SELECT o.id AS "orderId", o.order_no AS "orderNo", o.kind AS "kind", o.order_date AS "orderDate", COALESCE(sp.name, cu.name) AS "partnerName", i.id AS "orderItemId", i.material_id AS "materialId", m.code AS "materialCode", m.name AS "materialName", m.spec AS "spec", m.unit AS "unit", i.qty AS "qty", i.done_qty AS "doneQty", i.qty - i.done_qty + i.replenish_qty AS "openQty", COALESCE(i.delivery_date, o.delivery_date) AS "deliveryDate", COALESCE((SELECT SUM(r.qty) FROM wms_reservation r WHERE r.source_type = 'SALES' AND r.source_item_id = i.id), 0) AS "reservedQty", COALESCE((SELECT SUM(s.qty - s.frozen_qty) FROM wms_stock s WHERE s.material_id = i.material_id), 0) AS "availableQty", u.nickname AS "createByName" FROM scm_order_item i JOIN scm_order o ON o.id = i.order_id JOIN wms_material m ON m.id = i.material_id LEFT JOIN scm_supplier sp ON o.kind = 'PURCHASE' AND sp.id = o.partner_id LEFT JOIN scm_customer cu ON o.kind = 'SALES' AND cu.id = o.partner_id LEFT JOIN sys_user u ON u.id = o.create_by WHERE o.kind = #{kind} AND o.status IN ('APPROVED', 'PARTIAL') AND i.qty - i.done_qty + i.replenish_qty > 0 AND COALESCE(i.delivery_date, o.delivery_date) < #{today} AND o.partner_id = #{partnerId}
AND (o.order_no LIKE CONCAT('%', #{keyword}, '%') OR m.code LIKE CONCAT('%', #{keyword}, '%') OR m.name LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY COALESCE(i.delivery_date, o.delivery_date), o.id, i.id
